pub mod urna {
    pub struct Urna {
        pub votos: Vec<String>,
    }

    impl Urna {
        pub fn nova() -> Urna {
            Urna { votos: vec![] }
        }

        pub fn recebe(&mut self, voto: String) {
            self.votos.push(voto);
        }

        pub fn votos(&self) -> Vec<String> {
            self.votos.clone()
        }
    }

    pub fn empurra(urna: &mut Urna, voto: String) {
        super::urna::Urna::recebe(urna, voto);
    }

    pub fn lista(urna: &Urna) -> Vec<String> {
        super::urna::Urna::votos(urna)
    }
}

use std::collections::HashMap;
use urna::Urna;

pub fn apura(caixa: Urna) -> HashMap<String, i32> {
    let mut contagem = HashMap::new();
    for voto in urna::lista(&caixa) {
        *contagem.entry(voto).or_insert(0) += 1;
    }
    contagem
}

testsCode:
use desafio::apura;

#[test]
fn testa_a_urna_da_ana_e_do_bo() {
    let mut caixa = desafio::urna::Urna::nova();
    desafio::urna::empurra(&mut caixa, String::from("ana"));
    desafio::urna::empurra(&mut caixa, String::from("bo"));
    desafio::urna::empurra(&mut caixa, String::from("ana"));
    let c = apura(caixa);
    assert_eq!(c["ana"], 2);
    assert_eq!(c["bo"], 1);
}

#[test]
fn testa_a_urna_do_bo_so() {
    let mut caixa = desafio::urna::Urna::nova();
    desafio::urna::empurra(&mut caixa, String::from("bo"));
    desafio::urna::empurra(&mut caixa, String::from("bo"));
    desafio::urna::empurra(&mut caixa, String::from("bo"));
    let c = apura(caixa);
    assert_eq!(c["bo"], 3);
    assert_eq!(c.len(), 1);
}
